const payoutsInStatus = `-- name: PayoutsInStatus :many
SELECT p.id, p.user_id, p.kind, p.route, p.status, p.gross_kes, p.tax_kes, p.net_kes, p.msisdn, p.draw_result_id, p.originator_conversation_id, p.conversation_id, p.mpesa_receipt, p.idempotency_key, p.created_at, p.updated_at, p.tax_code, p.tax_rate, p.tax_rounding, p.status_requests, p.status_requested_at, p.status_originator, p.reason, p.approved_by, p.settled_by, p.settled_at, p.debt_offset_kes, p.refund_reason, p.refund_requested_by FROM payouts.payouts p
WHERE p.status = $1
  AND ($2::uuid IS NULL
       OR (p.created_at, p.id) > (SELECT a.created_at, a.id FROM payouts.payouts a WHERE a.id = $2::uuid))
ORDER BY p.created_at, p.id
LIMIT $3
`

type PayoutsInStatusParams struct {
	Status  string
	After   *string
	MaxRows int32
}

// Oldest first (the operator's queue); after (a payout id) continues a page from the payout after it.
func (q *Queries) PayoutsInStatus(ctx context.Context, arg PayoutsInStatusParams) ([]PayoutsPayout, error) {
	rows, err := q.db.Query(ctx, payoutsInStatus, arg.Status, arg.After, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PayoutsPayout
	for rows.Next() {
		var i PayoutsPayout
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Kind,
			&i.Route,
			&i.Status,
			&i.GrossKes,
			&i.TaxKes,
			&i.NetKes,
			&i.Msisdn,
			&i.DrawResultID,
			&i.OriginatorConversationID,
			&i.ConversationID,
			&i.MpesaReceipt,
			&i.IdempotencyKey,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TaxCode,
			&i.TaxRate,
			&i.TaxRounding,
			&i.StatusRequests,
			&i.StatusRequestedAt,
			&i.StatusOriginator,
			&i.Reason,
			&i.ApprovedBy,
			&i.SettledBy,
			&i.SettledAt,
			&i.DebtOffsetKes,
			&i.RefundReason,
			&i.RefundRequestedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

